    async def create_glue_record(
        self,
        domain_name: str,
        body: CreateGlueRecordDto,
        *,
        options: RequestOptions | None = None,
    ) -> GlueRecordCreateResponseDto:
        """Create a glue record

        Creates a host (glue record) at the registry so the domain can use a nameserver under itself, for
        example `ns1.example.com` for `example.com`, and stores it at LETO.

        - `hostname` must be exactly one label under the domain and is stored lower-case.
        - One IP address per host. A host name that already has a glue record is refused.
        - The domain must be active, not expired, registered at the registry and not update-locked.

        The response `data.id` is the `glueRecordId` used to delete it.

        Body fields:
        - `hostname` (required): Host name of the nameserver: exactly one label under the domain, for
          example `ns1.example.com` for `example.com` (`ns1.sub.example.com` is refused). Stored lower-case.
        - `ipAddress` (required): IPv4 or IPv6 address of the host. One address per host.

        Errors (LetoApiError, branch on error_code):
        - 400: - `GLUE_RECORD_HOSTNAME_INVALID_DOMAIN`: `hostname` is not one label under the domain. -
          `GLUE_RECORD_HOSTNAME_REQUIRED` / `GLUE_RECORD_IP_ADDRESS_REQUIRED`: a field is empty. -
          `GLUE_RECORD_IP_ADDRESS_INVALID_FORMAT`: `ipAddress` is not an IPv4 or IPv6 address. -
          `GLUE_RECORD_ALREADY_EXISTS`: this host name already has a glue record. -
          `GLUE_RECORD_CREATE_FAILED`: the registry refused the request. `data.reason` has the registry
          message. - `DOMAIN_UPDATE_LOCKED` (400): the domain has update lock on. Turn it off first. -
          `DOMAIN_INVALID_STATUS` (400): the domain is not active.
        - 404: - `DOMAIN_NOT_FOUND` (404): the domain is not in your account. - `DOMAIN_NOT_REGISTERED`
          (404): the domain has no registry registration yet.
        - 410: `DOMAIN_EXPIRED` (410): the domain has passed its expiry date.
        - 500: `GLUE_RECORD_CREATE_FAILED`: an unexpected error while creating the glue record.

        HTTP: `POST /api/v1/domain/{domainName}/glue-records`

        Args:
            domain_name: Domain name in your account
            body: Request body (fields listed above).
            options: Retries and extra headers for this call.

        Returns:
            GlueRecordCreateResponseDto: The response body, as documented.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        response = await self._transport.request(
            "POST",
            "/api/v1/domain/{domainName}/glue-records",
            path_params={"domainName": domain_name},
            body=body,
            options=options,
        )
        return cast(GlueRecordCreateResponseDto, response)

    async def delete_glue_record(
        self,
        domain_name: str,
        glue_record_id: str,
        *,
        options: RequestOptions | None = None,
    ) -> GlueRecordDeleteResponseDto:
        """Delete a glue record

        Deletes the host at the registry, then removes it at LETO. No request body. `glueRecordId` is the
        `id` from the create response or the glue record list (a LETO ID, not the registry host ID). The
        domain must be active, not expired, registered at the registry and not update-locked.

        Errors (LetoApiError, branch on error_code):
        - 400: - `GLUE_RECORD_DELETE_FAILED`: the registry refused the request (for example the host is
          still in use). `data.reason` has the registry message. - `BAD_REQUEST`: `glueRecordId` is not a
          valid UUID. - `DOMAIN_UPDATE_LOCKED` (400): the domain has update lock on. Turn it off first. -
          `DOMAIN_INVALID_STATUS` (400): the domain is not active.
        - 404: - `GLUE_RECORD_NOT_FOUND`: no glue record with this ID for the domain. - `DOMAIN_NOT_FOUND`
          (404): the domain is not in your account. - `DOMAIN_NOT_REGISTERED` (404): the domain has no
          registry registration yet.
        - 410: `DOMAIN_EXPIRED` (410): the domain has passed its expiry date.
        - 500: `GLUE_RECORD_DELETE_FAILED`: an unexpected error while deleting the glue record.

        HTTP: `DELETE /api/v1/domain/{domainName}/glue-records/{glueRecordId}`

        Args:
            domain_name: Domain name in your account
            glue_record_id: Glue record ID: `data.id` of the create response or `data.hosts[].id` of the
                list
            options: Retries and extra headers for this call.

        Returns:
            GlueRecordDeleteResponseDto: The response body, as documented.

        Raises:
            LetoError: Any failure; LetoApiError when the API answered with an error.
        """
        response = await self._transport.request(
            "DELETE",
            "/api/v1/domain/{domainName}/glue-records/{glueRecordId}",
            path_params={"domainName": domain_name, "glueRecordId": glue_record_id},
            options=options,
        )
        return cast(GlueRecordDeleteResponseDto, response)
